import {notFound} from "next/navigation";
import {sql} from "@/lib/db";
import {PageHeading,EmptyState} from "@/components/SiteShell";
import CompetitionBracket from "@/components/CompetitionBracket";
export const dynamic="force-dynamic";
export default async function CompetitionDetail({params}:{params:Promise<{id:string}>}){
 const {id}=await params;let c:any,fx:any[]=[],table:any[]=[];
 try{
  const r=await sql`SELECT * FROM competitions WHERE id=${id} LIMIT 1`;c=r[0];
  if(c){
   if(String(c.format)==="table_elimination"){
    // Backfill group assignments for competitions generated by older code.
    await sql`
     WITH team_counts AS (
      SELECT COUNT(*)::int AS total FROM competition_teams WHERE competition_id=${id}
     ), unassigned AS (
      SELECT ct.team_id, ROW_NUMBER() OVER (ORDER BY t.name ASC, ct.team_id ASC) AS rn
      FROM competition_teams ct JOIN teams t ON t.id=ct.team_id
      WHERE ct.competition_id=${id} AND ct.group_name IS NULL
     )
     UPDATE competition_teams ct
     SET group_name=CASE
      WHEN (SELECT total FROM team_counts)=12 THEN
       CASE WHEN unassigned.rn<=3 THEN 'A' WHEN unassigned.rn<=6 THEN 'B' WHEN unassigned.rn<=9 THEN 'C' ELSE 'D' END
      ELSE CASE WHEN unassigned.rn<=4 THEN 'A' WHEN unassigned.rn<=8 THEN 'B' WHEN unassigned.rn<=12 THEN 'C' ELSE 'D' END
     END
     FROM unassigned WHERE ct.competition_id=${id} AND ct.team_id=unassigned.team_id
    `;
   }
   fx=await sql`SELECT f.*,ht.name home_name,at.name away_name FROM fixtures f LEFT JOIN teams ht ON ht.id=f.home_team_id LEFT JOIN teams at ON at.id=f.away_team_id WHERE f.competition_id=${id} ORDER BY f.stage,f.group_name,f.matchday NULLS LAST,f.created_at`;
   table=await sql`SELECT ct.group_name,t.name,COALESCE(SUM(CASE WHEN f.home_team_id=t.id THEN f.home_score WHEN f.away_team_id=t.id THEN f.away_score ELSE 0 END),0)::int gf,COALESCE(SUM(CASE WHEN f.home_team_id=t.id THEN f.away_score WHEN f.away_team_id=t.id THEN f.home_score ELSE 0 END),0)::int ga,COUNT(f.id)::int played,COUNT(f.id) FILTER(WHERE (f.home_team_id=t.id AND f.home_score>f.away_score) OR (f.away_team_id=t.id AND f.away_score>f.home_score))::int won,COUNT(f.id) FILTER(WHERE f.home_score=f.away_score)::int drawn FROM competition_teams ct JOIN teams t ON t.id=ct.team_id LEFT JOIN fixtures f ON f.competition_id=ct.competition_id AND f.status='confirmed' AND (f.home_team_id=t.id OR f.away_team_id=t.id) AND (${String(c.format)==='champions'} = FALSE OR f.stage <> 'knockout') AND (${String(c.format)==='table_elimination'} = FALSE OR f.stage='group') WHERE ct.competition_id=${id} GROUP BY ct.group_name,t.id,t.name`;
  }
 }catch{} if(!c)notFound();
 const grouped:Record<string,any[]>={};for(const row of table){const g=row.group_name||"League";(grouped[g]??=[]).push({...row,points:row.won*3+row.drawn,gd:row.gf-row.ga});}
 for(const rows of Object.values(grouped))rows.sort((a,b)=>b.points-a.points||b.gd-a.gd||b.gf-a.gf||a.name.localeCompare(b.name));
 const overall=table.map((r:any)=>({...r,points:r.won*3+r.drawn,gd:r.gf-r.ga})).sort((a:any,b:any)=>b.points-a.points||b.gd-a.gd||b.gf-a.gf);
 const isTwelveTeamThreeGroups=c.format==="table_elimination"&&table.length===12&&Object.keys(grouped).length===3&&Object.values(grouped).every((list:any)=>list.length===4);
 const isTwelveTeamFourGroups=c.format==="table_elimination"&&table.length===12&&Object.keys(grouped).length===4&&Object.values(grouped).every((list:any)=>list.length===3);
 const thirdPlaced=isTwelveTeamThreeGroups?Object.values(grouped).map((list:any)=>list[2]).filter(Boolean).sort((a:any,b:any)=>b.points-a.points||b.gd-a.gd||b.gf-a.gf||a.name.localeCompare(b.name)):[];
 const bestThirdNames=new Set(thirdPlaced.slice(0,2).map((r:any)=>r.name));
 const isQualified=(row:any,index:number)=>isTwelveTeamThreeGroups?(index<2||(index===2&&bestThirdNames.has(row.name))):isTwelveTeamFourGroups?index<2:index<3;
 return <main className="container"><PageHeading eyebrow="COMPETITION PROFILE" title={c.name} description={c.description||"Official VMF competition information, fixtures and results."}/>
 <section className="content-section"><div className="stat-grid"><div className="stat-card"><strong>{c.season||"—"}</strong><span>Season</span></div><div className="stat-card"><strong>{c.format==="table_elimination"?"Table + Elimination":c.format==="champions"?"Champions Format":c.format==="elimination"?"Elimination":"League"}</strong><span>Tournament type</span></div><div className="stat-card"><strong>{c.status}</strong><span>Status</span></div><div className="stat-card"><strong>{fx.length}</strong><span>Fixtures</span></div></div>{c.format==="table_elimination"&&<p className="notice" style={{marginTop:18}}>{isTwelveTeamThreeGroups?"Four groups of three teams. The top two in each group qualify (8 teams total); all third-placed teams are eliminated.":isTwelveTeamFourGroups?"Four groups of three teams. The top two in each group qualify (8 teams total); all third-placed teams are eliminated.":"Four groups of four teams. The top three in each group qualify for the 12-team elimination bracket; the fourth-placed team is eliminated."}</p>}
 {Object.keys(grouped).sort().map(g=><div key={g}><div className="section-head" style={{marginTop:38}}><h2>{g==="League"?"League table":`Group ${g}`}</h2></div><div className="table-wrap"><table className="data-table"><thead><tr><th>#</th><th>Team</th><th>P</th><th>W</th><th>D</th><th>GF</th><th>GA</th><th>GD</th><th>Pts</th>{c.format==="table_elimination"&&<th>Qualification</th>}</tr></thead><tbody>{grouped[g].map((r:any,i:number)=><tr key={r.name}><td>{i+1}</td><td>{r.name}</td><td>{r.played}</td><td>{r.won}</td><td>{r.drawn}</td><td>{r.gf}</td><td>{r.ga}</td><td>{r.gd>0?`+${r.gd}`:r.gd}</td><td><b>{r.points}</b></td>{c.format==="table_elimination"&&<td><span className="pill" style={{color:isQualified(r,i)?"#15803d":"#b91c1c"}}>{isQualified(r,i)?"QUALIFIED":"ELIMINATED"}</span></td>}</tr>)}</tbody></table></div></div>)}
 {c.format==="champions"&&<><div className="section-head" style={{marginTop:42}}><h2>Overall ranking · Repechage</h2><p>Top 8 qualify directly. Remaining teams are ranked by points, goal difference and goals scored.</p></div><div className="table-wrap"><table className="data-table"><thead><tr><th>#</th><th>Team</th><th>GD</th><th>Pts</th><th>Qualification</th></tr></thead><tbody>{overall.map((r:any,i:number)=><tr key={r.name}><td>{i+1}</td><td>{r.name}</td><td>{r.gd}</td><td>{r.points}</td><td>{i<8?"Direct qualification":"Repechage ranking"}</td></tr>)}</tbody></table></div></>}
 <div className="section-head" style={{marginTop:45}}><h2>{c.format==="champions"?"UEFA league phase fixtures & results":"Group-stage fixtures & results"}</h2></div>{fx.filter(f=>f.stage!=="knockout").length?<div className="table-wrap"><table className="data-table"><thead><tr><th>{c.format==="champions"?"Phase":"Group"}</th><th>Matchday</th><th>Home</th><th>Score</th><th>Away</th><th>Status</th></tr></thead><tbody>{fx.filter(f=>f.stage!=="knockout").map(f=><tr key={f.id}><td>{f.stage==="group"?`Group ${f.group_name||"—"}`:f.stage||"League"}</td><td>{f.matchday??"—"}</td><td>{f.home_name||"TBC"}</td><td><b>{f.home_score??"—"} : {f.away_score??"—"}</b></td><td>{f.away_name||"TBC"}</td><td><span className="pill">{f.status}</span></td></tr>)}</tbody></table></div>:<EmptyState title="Fixtures coming soon" detail="The schedule will be displayed here once it has been generated."/>}{["table_elimination","champions"].includes(String(c.format))&&<><div className="section-head" style={{marginTop:48}}><h2>Knockout bracket</h2><p>Results and progression are updated automatically after each round is confirmed.</p></div><CompetitionBracket theme={c.format==="champions"?(/europa/i.test(String(c.name))?"europa":"champions"):"classic"} uefa={c.format==="champions"} matches={fx.filter(f=>f.stage==="knockout").map(f=>({...f,round_name:f.round_name||null}))}/></>}</section></main>;
}
